package com.lock4.finalapp
import android.accessibilityservice.AccessibilityService;import android.view.accessibility.AccessibilityEvent;import android.view.*;import android.graphics.Color;import android.widget.TextView
class LockService:AccessibilityService(){private var overlay:View?=null;override fun onAccessibilityEvent(e:AccessibilityEvent?){if(e?.eventType!=AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED||!LockState.enabled)return;val pkg=e.packageName?.toString()?:return;val p=getSharedPreferences("lock4",0);if(p.getBoolean("blocked_$pkg",false)&&pkg!=packageName)show()}
private fun show(){if(overlay!=null)return;val wm=getSystemService(WINDOW_SERVICE) as WindowManager;val v=TextView(this).apply{text="LOCK//4\n\nLOCK-IN ACTIVE\n\nThis app is blocked for your study session.\n\nReturn to LOCK//4 to end the session.";textSize=21f;gravity=17;setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(9,11,14))};val lp=WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,-3);wm.addView(v,lp);overlay=v}
override fun onInterrupt(){};override fun onDestroy(){overlay?.let{(getSystemService(WINDOW_SERVICE) as WindowManager).removeView(it)};overlay=null;super.onDestroy()}}
